        graph.addEdge(1, 2, 3);
        graph.addEdge(2, 3, 2);
        graph.addEdge(3, 4, 10);

        ArrayList<Integer> result = dijkstra(graph, src);
        for (int d : result)
            System.out.print(d + " ");
        System.out.println();
    }
}

